import { loadFont } from "@remotion/google-fonts/Montserrat";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// MVOX FROTA · Criativo 04 v5 (17/10: papelada com as imagens que a Marcelly mandou, public/guilherme/ia-N.jpg). Base: v2 "Quem tá no controle?" (cliente Guilherme Saas). Igual à v1 (MvoxControle.tsx) com a voz do o locutor (17/10):
// cenas no tempo da voz antiga, TMAP converte o tempo da voz nova. Legenda mais baixa e abertura saindo do fundo chapado para a foto.
// Material: 3 artes de depoimento do cliente (retratos recortados em public/guilherme/rosto-*.jpg, placa do Wilson desfocada),
// as 3 telas do app (tela-*.png) e fotos de caminhão do Pexels já usadas no criativo 03 v2 (foto-*.jpg, placas desfocadas).
// Voz: Roger (src/c04/voz-c04-v2.wav = v1 com silêncios longos encurtados). Tempos = tempos da voz-c04-v2; o vídeo tem LEAD.
// Legenda no estilo que o cliente mandou: branca grossa com contorno preto, palavra falada em amarelo, um pouco abaixo do meio.
const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const MC5_FPS = 30;
const LEAD = 0.2;
const END = 35.2;
export const MC5_FRAMES = Math.round((END + LEAD) * MC5_FPS);

const TMAP: [number, number][] = [[0.091, 0.11], [0.852, 0.47], [1.012, 0.71], [2.052, 1.82], [2.312, 2.12], [2.433, 2.22], [2.913, 3.4], [3.093, 3.57], [3.213, 3.81], [3.313, 3.93], [3.813, 5.09], [4.574, 6.22], [4.814, 6.46], [5.034, 6.56], [5.955, 7.83], [6.775, 8.01], [6.835, 8.07], [6.935, 8.25], [7.156, 8.53], [7.796, 9.31], [8.116, 9.77], [8.356, 10.15], [8.536, 10.51], [8.957, 11.23], [9.757, 12.38], [9.837, 12.46], [10.838, 13.12], [11.058, 13.3], [11.198, 13.54], [11.518, 14.06], [11.638, 14.22], [12.599, 14.96], [12.939, 15.22], [13.079, 15.32], [13.139, 15.38], [13.84, 16.0], [14.38, 16.5], [14.921, 17.0], [14.981, 17.08], [15.341, 17.58], [15.441, 17.72], [15.561, 17.86], [16.522, 19.32], [16.662, 19.46], [16.762, 19.52], [17.142, 20.02], [17.322, 20.26], [17.602, 20.66], [18.123, 21.48], [18.403, 21.72], [18.803, 22.14], [19.343, 22.73], [19.584, 23.03], [19.764, 23.35], [20.224, 24.13], [20.284, 24.23], [20.464, 24.47], [21.265, 25.71], [21.345, 25.83], [21.425, 25.91], [22.125, 26.79], [22.325, 26.96], [22.425, 27.04], [23.186, 27.77], [23.286, 27.99], [23.746, 28.65], [24.407, 29.65], [24.647, 29.89], [25.107, 30.35], [25.247, 30.49], [25.627, 31.01], [25.788, 31.25], [26.028, 31.6], [26.188, 31.74], [26.729, 32.58], [26.869, 32.7], [27.33, 33.32], [27.471, 33.54], [28.133, 34.18], [28.233, 34.26], [28.674, 34.68], [28.995, 35.12], [29.216, 35.51], [29.356, 35.73], [29.597, 35.99], [30.219, 36.71], [30.64, 37.23], [30.761, 37.49], [31.202, 38.15], [31.844, 38.89], [32.145, 39.46], [32.245, 39.58], [32.486, 40.02], [32.686, 40.32]];
// tempo da voz do o locutor como saiu do ElevenLabs, sem mexer nas pausas (v anterior espalhava as frases e soou com pausas) → tempo da voz antiga, em que as cenas foram feitas; fora da tabela anda junto
const toOld = (tn: number) => {
  if (tn <= TMAP[0][0]) return tn - TMAP[0][0] + TMAP[0][1];
  for (let i = 1; i < TMAP.length; i++) if (tn <= TMAP[i][0]) { const [a0, b0] = TMAP[i - 1], [a1, b1] = TMAP[i]; return b0 + ((tn - a0) / Math.max(1e-6, a1 - a0)) * (b1 - b0); }
  const [a, b] = TMAP[TMAP.length - 1]; return b + (tn - a);
};

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;

// identidade tirada das telas do app
const NAVY = "#042340";
const BLUE = "#1B8CEA";
const BTN = "#0A4BD6";
const WHITE = "#FFFFFF";

// trocas de cena (tempo da voz)
const T2 = 3.3, T3 = 7.7, T4 = 12.3, T5 = 19.25, T6 = 25.65, T7 = 32.5;

type Lay = { H: number; title: number; mid: number; cap: number; s: number };
const LAY_V: Lay = { H: 1920, title: 300, mid: 960, cap: 1440, s: 1 };
const LAY_F: Lay = { H: 1350, title: 80, mid: 556, cap: 1050, s: 0.72 };
// posição vertical: no 9:16 é o próprio valor; no feed, a mesma coluna comprimida (230 → 30, 1920 → 1247)
const Y = (L: Lay, yv: number) => (L.H === 1920 ? yv : 30 + (yv - 230) * 0.72);

// texto: entra desfocado com leve escala, assenta e fica parado; sai desfocando no mesmo lugar
const blurIn = (t: number, at: number, out?: number, d = 0.38): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), filter: `blur(${((1 - e) * 14 + o * 12).toFixed(1)}px)`, transform: `scale(${(0.88 + 0.12 * e).toFixed(4)})` };
};
// impacto: entra grande e assenta com um tranco
const slam = (t: number, at: number, out?: number): React.CSSProperties => {
  const e = k(t, at, 0.32);
  const o = out === undefined ? 0 : lin(t, out, out + 0.16);
  return { opacity: Math.min(1, e * 3) * (1 - o), transform: `scale(${(1.5 - 0.5 * e).toFixed(4)})`, filter: `blur(${((1 - e) * 10 + o * 12).toFixed(1)}px)` };
};

type Ln = { w: string; at: number; size: number; band?: boolean; color?: string; out?: number; fx?: "slam" };
const Title: React.FC<{ t: number; L: Lay; lines: Ln[]; top?: number; dark?: boolean }> = ({ t, L, lines, top, dark }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top: top ?? L.title, display: "flex", flexDirection: "column", alignItems: "center", gap: 14 * L.s }}>
    {lines.map((l, i) => {
      const size = l.size * L.s;
      const fx = l.fx === "slam" ? slam(t, l.at, l.out) : blurIn(t, l.at, l.out);
      return (
        <div key={i} style={{ fontFamily: F, fontWeight: 900, fontSize: size, lineHeight: 1.05, letterSpacing: "-0.03em", whiteSpace: "nowrap", textTransform: "uppercase", color: l.band ? WHITE : l.color ?? (dark ? WHITE : NAVY), ...(l.band ? { background: BTN, padding: `${size * 0.1}px ${size * 0.3}px ${size * 0.14}px`, borderRadius: size * 0.22 } : {}), ...fx }}>
          {l.w}
        </div>
      );
    })}
  </div>
);

// ───────── marca ─────────
const TruckIcon: React.FC<{ s: number; c?: string }> = ({ s, c = BLUE }) => (
