// ───────── celular com os prints reais ─────────
const SCR = { viagens: "guilherme/tela-viagens.png", painel: "guilherme/tela-painel.png", acerto: "guilherme/tela-acerto.png" };
const SCR_W = { viagens: 556, painel: 524, acerto: 554 };
type ScrKey = keyof typeof SCR;
const Phone: React.FC<{ w: number; scr: ScrKey; scr2?: ScrKey; swap?: number; ring?: { x: number; y: number; w: number; h: number; o: number } }> = ({ w, scr, scr2, swap = 0, ring }) => {
  const sw = w * 0.92;
  const sh = sw * 2.165;
  const img = (s: ScrKey) => <Img src={staticFile(SCR[s])} style={{ position: "absolute", left: 0, top: 0, width: sw, height: "auto" }} />;
  const u = sw / SCR_W[scr2 && swap > 0.5 ? scr2 : scr];
  return (
    <div style={{ width: w, height: sh + w * 0.08, borderRadius: w * 0.14, background: "#0B0F14", padding: w * 0.04, boxSizing: "border-box", boxShadow: "0 60px 120px rgba(2,14,30,0.45), 0 10px 30px rgba(2,14,30,0.25), inset 0 0 0 3px #2B3440" }}>
      <div style={{ width: sw, height: sh, borderRadius: w * 0.11, overflow: "hidden", position: "relative", background: WHITE }}>
        <div style={{ position: "absolute", inset: 0, transform: `translateX(${(-swap * sw).toFixed(1)}px)` }}>{img(scr)}</div>
        {scr2 ? <div style={{ position: "absolute", inset: 0, transform: `translateX(${((1 - swap) * sw).toFixed(1)}px)` }}>{img(scr2)}</div> : null}
        {ring && ring.o > 0 ? (
          <div style={{ position: "absolute", left: ring.x * u - 6, top: ring.y * u - 6, width: ring.w * u + 12, height: ring.h * u + 12, borderRadius: 18 * u, border: `${5 * u}px solid ${BTN}`, boxShadow: `0 0 0 ${9 * u}px rgba(10,75,214,0.18)`, opacity: ring.o, boxSizing: "border-box" }} />
        ) : null}
