];
// blocos de até ~14 letras; quebra depois de pontuação
const CHUNKS: W[][] = (() => {
  const out: W[][] = [];
  let cur: W[] = [];
  for (const w of WORDS) {
    const len = cur.reduce((n, x) => n + x[0].length + 1, 0);
    if (cur.length && len + w[0].length > 14) { out.push(cur); cur = []; }
    cur.push(w);
    if (/[.,!?:]$/.test(w[0])) { out.push(cur); cur = []; }
  }
  if (cur.length) out.push(cur);
  return out;
})();
const YELLOW = "#FFE11A";
const Captions: React.FC<{ t: number; L: Lay }> = ({ t, L }) => {
  const i = CHUNKS.findIndex((c, n) => t >= c[0][1] - 0.04 && (n === CHUNKS.length - 1 || t < CHUNKS[n + 1][0][1] - 0.04));
  if (i < 0) return null;
  const c = CHUNKS[i];
  const end = c[c.length - 1][1] + 1.2;
  if (t > end && (i === CHUNKS.length - 1 || CHUNKS[i + 1][0][1] - end > 0.3)) return null;
  const e = pop(t, c[0][1] - 0.04, 0.22);
  const size = 82 * (L.H === 1920 ? 1 : 0.8);
  return (
    <div style={{ position: "absolute", left: 60, right: 60, top: L.cap - size * 0.6, display: "flex", justifyContent: "center", transform: `scale(${(0.86 + 0.14 * e).toFixed(3)})`, opacity: Math.min(1, e * 2) }}>
