      <AbsoluteFill style={{ background: WHITE, opacity: 0.5 * bump(t, 0.68, 0.32) }} />
      <Title t={t} L={L} dark top={mix(L.mid - 160 * L.s, L.title, up)} lines={[{ w: "você tem", at: 0.11, size: mix(110, 84, up), fx: "slam" }, { w: "caminhão?", at: 0.71, size: 128, band: true, fx: "slam" }]} />
    </AbsoluteFill>
