};

// Cena 2: a papelada em foto real — o dono perdido nos papéis, depois um mosaico de papel, caderno, notinhas e celular
const TILES: [string, number, number, number, number][] = [["ia-8", 30, 55, 5.09, 1.05], ["ia-6", 45, 50, 5.3, 1.05], ["ia-4", 60, 50, 6.22, 1.05], ["ia-7", 45, 45, 6.45, 1.05]];
const SceneDesk: React.FC<{ t: number; L: Lay }> = ({ t, L }) => {
  const H = L.H;
  const grid = t >= 5.05;
  const g = 8;
  const tw = (1080 - g) / 2, th = (H - g) / 2;
  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {!grid ? <Photo src="ia-1" fx={24} fy={45} h={H} z={mix(1.25, 1.08, io(t, T2, 5.05))} dx={mix(-40, 30, lin(t, T2, 5.05))} /> : null}
      {grid
        ? TILES.map(([src, fx, fy, at, z], i) => {
            const e = k(t, at, 0.35);
            const x = (i % 2) * (tw + g), y = Math.floor(i / 2) * (th + g);
            const shake = Math.sin(t * 50 + i) * 8 * bump(t, 6.56, 0.5);
            return (
              <div key={src} style={{ position: "absolute", left: x + shake, top: y, width: tw, height: th, overflow: "hidden", opacity: Math.min(1, e * 2), transform: `scale(${(0.7 + 0.3 * e).toFixed(3)})` }}>
                <Photo src={src} fx={fx} fy={fy} w={tw} h={th} z={z * mix(1.1, 1.0, lin(t, at, T3))} />
              </div>
            );
          })
        : null}
      <Veil L={L} />
      <Title t={t} L={L} dark lines={[{ w: "quem tá no", at: 3.4, size: 76, out: 5.0 }, { w: "controle?", at: 3.93, size: 120, band: true, out: 5.0, fx: "slam" }]} />
      <Title t={t} L={L} dark lines={[{ w: "você", at: 5.09, size: 120, fx: "slam" }, { w: "ou a papelada?", at: 6.22, size: 84, band: true, fx: "slam" }]} />
    </AbsoluteFill>
  );
};

