const MvoxControle: React.FC<{ L: Lay }> = ({ L }) => {
  const f = useCurrentFrame();
  const t = toOld(f / MC5_FPS - LEAD);
  let scene: React.ReactNode;
  if (t < T2) scene = <SceneOpen t={t} L={L} />;
  else if (t < T3) scene = <SceneDesk t={t} L={L} />;
  else if (t < T4) scene = <SceneIntro t={t} L={L} />;
  else if (t < T5)
    scene = <SceneDepo t={t} L={L} p={PEOPLE[0]} from={T4} to={T5} bg="foto-bau" bgFx={62} segs={[["O MVOX Frota "], ["facilitou demais o meu acerto com os motoristas.", 16.0], [" Antes era demorado e às vezes surgiam dúvidas, agora ficou tudo mais resolvido."]]} chips={[{ at: 17.08, text: "acerto com motoristas" }]} />;
  else if (t < T6)
    scene = <SceneDepo t={t} L={L} p={PEOPLE[1]} from={T5} to={T6} bg="foto-aerea" bgFx={50} segs={[["Antes eu tentava controlar tudo "], ["pelo WhatsApp e pelo caderno.", 23.03], [" Depois que coloquei meus quatro caminhões no MVOX Frota, facilitou demais."]]} chips={[{ at: 23.35, out: 24.85, text: "whatsapp e caderno", icon: "x" }, { at: 24.95, text: "tudo no mvox frota", icon: "ok" }]} />;
  else if (t < T7)
    scene = <SceneDepo t={t} L={L} p={PEOPLE[2]} from={T6} to={T7} bg="foto-volvo" bgFx={60} segs={[["Tenho só um caminhão, mas coloquei no MVOX Frota. Tenho tudo "], ["na palma da mão,", 31.01], [" cada parafuso que gasto com meu caminhão, que é "], ["meu ganha-pão.", 27.99]]} chips={[{ at: 27.99, out: 31.0, text: "meu ganha-pão" }, { at: 31.25, text: "na palma da mão" }]} phoneAt={29.65} />;
  else scene = <SceneEnd t={t} L={L} />;
  // transições, cada uma de um jeito
  const whip = Math.abs(t - T2) < 0.18 ? 1 - Math.abs(t - T2) / 0.18 : 0;
  const flash = t > T3 - 0.08 && t < T3 + 0.25 ? 1 - Math.abs(t - T3) / (t < T3 ? 0.08 : 0.25) : 0;
  const wipeUp = t > T4 - 0.3 && t < T4 ? lin(t, T4 - 0.3, T4) : 0;
  const wipeL = t > T5 - 0.28 && t < T5 + 0.28 ? (t < T5 ? lin(t, T5 - 0.28, T5) : 1 - lin(t, T5, T5 + 0.28)) : 0;
  const zoomBlur = Math.abs(t - T6) < 0.2 ? 1 - Math.abs(t - T6) / 0.2 : 0;
  const iris = t > T7 - 0.35 && t < T7 ? io(t, T7 - 0.35, T7) : 0;
  return (
    <AbsoluteFill style={{ background: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ transform: whip ? `translateX(${((t < T2 ? -1 : 1) * whip * 200).toFixed(1)}px)` : zoomBlur ? `scale(${(1 + zoomBlur * 0.25).toFixed(3)})` : undefined, filter: whip ? `blur(${(whip * 26).toFixed(1)}px)` : zoomBlur ? `blur(${(zoomBlur * 18).toFixed(1)}px)` : undefined }}>{scene}</AbsoluteFill>
      {flash > 0 ? <AbsoluteFill style={{ background: WHITE, opacity: flash }} /> : null}
      {wipeUp > 0 ? <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: L.H * wipeUp, background: NAVY }} /> : null}
      {wipeL > 0 ? <div style={{ position: "absolute", top: 0, bottom: 0, left: t < T5 ? 0 : undefined, right: t >= T5 ? 0 : undefined, width: 1080 * wipeL, background: BTN }} /> : null}
      {iris > 0 ? <div style={{ position: "absolute", left: 540, top: L.H / 2, width: 2400 * iris, height: 2400 * iris, marginLeft: -1200 * iris, marginTop: -1200 * iris, borderRadius: "50%", background: NAVY }} /> : null}
      <Captions t={t} L={L} />
    </AbsoluteFill>
  );
};

